ready(() => {
  const advancedSettingsButtons: NodeListOf<HTMLButtonElement> =
    document.querySelectorAll('[data-behavior=toggle-visibility]');

  advancedSettingsButtons.forEach((button) => {
    const target = document.getElementById(
      button.dataset.toggleVisibility!,
    ) as HTMLElement;
    const onText = button.getAttribute('data-toggle-text-on');
    const offText = button.getAttribute('data-toggle-text-off');

    target.hidden = true;

    button.addEventListener('click', () => {
      const btn = button as HTMLButtonElement;

      if (target.hidden) {
        target.hidden = false;
        btn.textContent = offText;
      } else {
        target.hidden = true;
        btn.textContent = onText;
      }
    });
  });
});

Dropzone.autoDiscover = false;

const showPreviousImage = (dropzone) => {
  // Show existing image in preview-zone
  const fileUrl = document.getElementsByName('file_url')[0];
  if (fileUrl && fileUrl.value !== '') {
    const mockFile = {
      name: fileUrl.value.split('/')[fileUrl.value.split('/').length - 1],
    };
    dropzone.emit('addedfile', mockFile);
    dropzone.files.push(mockFile);
    const currentImage = mockFile.previewElement.querySelector(
      '[data-dz-thumbnail]',
    );
    currentImage.alt = mockFile.name;
    currentImage.src = fileUrl.value;
    dropzone.emit('success', mockFile);
  }
};

